import{_ as e,o as a,c as r,a5 as d}from"./chunks/framework.BF53ZjCA.js";const p=JSON.parse('{"title":"单斜晶系","description":"","frontmatter":{"title":"单斜晶系","crystalSystem":"monoclinic"},"headers":[],"relativePath":"zh/classification/crystal-systems/monoclinic.md","filePath":"zh/classification/crystal-systems/monoclinic.md","lastUpdated":1790876393000}'),l={name:"zh/classification/crystal-systems/monoclinic.md"};function n(i,t,s,o,c,h){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="单斜晶系" tabindex="-1">单斜晶系 <a class="header-anchor" href="#单斜晶系" aria-label="Permalink to &quot;单斜晶系&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>单斜晶系三条不等长轴，其中两条正交，第三条 b 轴倾斜。晶体为 二轴晶。主要解理平行于 (010) 轴面。软玉（透闪石质）、大多数 长石族矿物属此晶系。</p><h2 id="晶体学参数" tabindex="-1">晶体学参数 <a class="header-anchor" href="#晶体学参数" aria-label="Permalink to &quot;晶体学参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>值</th></tr></thead><tbody><tr><td>晶轴</td><td>a ≠ b ≠ c</td></tr><tr><td>夹角</td><td>α = γ = 90°, β ≠ 90°</td></tr><tr><td>对称性等级</td><td>low-medium</td></tr><tr><td>光学分类</td><td>biaxial</td></tr><tr><td>光性</td><td>+ or −</td></tr><tr><td>双折射率范围</td><td>0.015–0.105</td></tr><tr><td>解理</td><td>pinacoidal (single good cleavage)</td></tr><tr><td>常见晶形</td><td>斜柱状、板状，常出现双晶</td></tr></tbody></table><h2 id="主要宝石" tabindex="-1">主要宝石 <a class="header-anchor" href="#主要宝石" aria-label="Permalink to &quot;主要宝石&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>折射率</th><th>比重</th></tr></thead><tbody><tr><td>Nephrite (Jade)</td><td>1.606–1.632</td><td>2.93–3.18</td></tr><tr><td>Orthoclase</td><td>1.518–1.526</td><td>2.55–2.63</td></tr><tr><td>Moonstone (Feldspar)</td><td>1.518–1.530</td><td>2.55–2.58</td></tr><tr><td>Spodumene (Kunzite/Hiddenite)</td><td>1.660–1.681</td><td>3.17–3.19</td></tr><tr><td>Diopside</td><td>1.664–1.730</td><td>3.22–3.38</td></tr><tr><td>Malachite</td><td>1.655–1.909</td><td>3.25–4.10</td></tr><tr><td>Sphene (Titanite)</td><td>1.843–2.110</td><td>3.52–3.54</td></tr><tr><td><em>详见<a href="./../intro.html">分类总览</a>。</em></td><td></td><td></td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://www.open.edu/openlearn/science-maths-technology/an-introduction-minerals-and-rocks-under-the-microscope/content-section-1.6.3/?tip=linktip" target="_blank" rel="noreferrer">Open University：晶体系统</a><span>晶系、晶轴关系与对称性基础</span><small>打开来源 ↗</small></li><li><a href="https://australian.museum/learn/minerals/what-are-minerals/crystallography/" target="_blank" rel="noreferrer">Australian Museum：晶体学</a><span>晶体结构与矿物学分类背景</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/summer-2025-phenomenal-gemstones" target="_blank" rel="noreferrer">GIA：现象宝石的结构</a><span>宝石学中的结构与光学观察线索</span><small>打开来源 ↗</small></li></ul></aside>',8)])])}const b=e(l,[["render",n]]);export{p as __pageData,b as default};
